      reader.onload = e => {
        this.previewUrl = e.target.result;
      };
      reader.readAsDataURL(input.files[0]);
    }
  }
  onSubmit() {
    if (this.carouselForm.invalid || !this.selectedFile) {
      alert("Please complete all fields.");
      return;
    }
